#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  # Nothing shows while typing or pasting, so say what arrived.
  if [[ -n "$input" ]]; then
    note "✓ übernommen (${#input} Zeichen)"
  elif [[ -n "$current" ]]; then
    input="$current"
    note "✓ bisheriger Wert bleibt"
  fi
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Set up the Modellbahn-Shop on its own server (a Strato VPS with Ubuntu 24.04), run as
# root from the cloned repository: ./scripts/einrichten.sh  (docs/BETRIEB.md, step 4).
# Every value lands in .env next to this repository; a second run keeps what is there.

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$REPO_DIR/.env"
DEFAULT_SITE="neu.adp-modelle.de"
GITHUB_REPO="nelebolsewig-droid/modellbahn-shop"
# shellcheck source=scripts/gemeinsam.sh
source "$REPO_DIR/scripts/gemeinsam.sh"
# Root's SSH configuration, which gets the host alias of the Storage Box (ADR 0025).
OFFSITE_SSH_CONFIG="/root/.ssh/config"
# The restic repository's folder on the Storage Box.
OFFSITE_REPO_PATH="modellbahn"
MONITOR_CRON="/etc/cron.d/modellbahn-ueberwachung"

# The value of KEY in .env unless it is one of the development placeholders.
real_value() {
  local value
  value=$(_existing "$1" || true)
  case "$value" in
    ""|localhost|https://localhost|internal|development|*Muster*|*example.com*|12345) return 1 ;;
  esac
  printf '%s' "$value"
}

# iban_ok IBAN: format and check digits (ISO 13616, modulo 97); the example account of
# .env.example does not count, production refuses it.
iban_ok() {
  python3 - "$1" <<'PY'
import re, sys
iban = "".join(sys.argv[1].split()).upper()
ok = re.fullmatch(r"[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}", iban) is not None
ok = ok and int("".join(str(int(c, 36)) for c in iban[4:] + iban[:4])) % 97 == 1
sys.exit(0 if ok and iban != "DE89370400440532013000" else 1)
PY
}

# ask_real KEY "Prompt" [default]: like ask, but a development placeholder in .env is not
# offered as the current value; the default is, if given.
ask_real() {
  local key="$1" prompt="$2" fallback="${3:-}" current
  current=$(real_value "$key" || true)
  if [[ -z "$current" ]]; then
    sed -i "/^${key}=/d" "$ENV_FILE"
    [[ -n "$fallback" ]] && printf "%s='%s'\n" "$key" "$fallback" >> "$ENV_FILE"
  fi
  ask "$key" "$prompt"
}

# keep_or_generate KEY COMMAND: a secret stays once set (a new database password would lock
# the shop out of its own data); the development value from .env.example is replaced by
# what COMMAND prints.
keep_or_generate() {
  local key="$1" current example
  current=$(_existing "$key" || true)
  example=$(ENV_FILE="$REPO_DIR/.env.example" _existing "$key" || true)
  if [[ -n "$current" && "$current" != "$example" ]]; then
    note "$key ist schon gesetzt und bleibt."
    return
  fi
  write_env "$key" "$(eval "$2")"
}

# The server's public IPv4 address: on its interface, else as the internet sees it.
public_ipv4() {
  local address
  address=$(ip -4 -o addr show scope global 2>/dev/null | awk '{print $4}' | cut -d/ -f1 | head -n1)
  if [[ -z "$address" || "$address" =~ ^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.) ]]; then
    address=$(curl -4 -fsS --max-time 10 https://api.ipify.org 2>/dev/null || true)
  fi
  printf '%s' "$address"
}

public_ipv6() {
  ip -6 -o addr show scope global 2>/dev/null | awk '{print $4}' | cut -d/ -f1 | head -n1
}

# dhl_stage asks for DHL's access (ADR 0023). A stage of the wizard, and on its own with
# `einrichten.sh dhl`, so DHL can be set up or switched on without the other stages.
dhl_stage() {
stage "DHL-Versandlabels (kann später nachgeholt werden)"
say "Das Stellwerk bucht das DHL-Label für den Etikettendrucker (100 × 150 mm), sobald das Paket"
say "gepackt ist, und die Sendungsnummer kommt mit Verfolgungslink in die Versandmail."
say "Dafür braucht es den API-Schlüssel eurer App im DHL-Entwicklerportal und für echte Labels"
say "einen Systembenutzer des DHL-Geschäftskundenportals mit eurer Kundennummer (EKP)."
note "Ohne DHL tragt ihr die Sendungsnummer wie bisher von Hand ein."
printf '\n'
if ! confirm "DHL jetzt anbinden?"; then
  write_env MB_DHL_MODE "off"
  SKIPPED+=("DHL-Labels: ./scripts/einrichten.sh dhl, sobald der API-Schlüssel da ist")
  pause
  return
fi
open_url "https://developer.dhl.com/user/apps"
step "Apps → eure App → „Show key“: den ${BOLD}API Key${RESET} kopieren (nicht das API Secret)."
step "Hier einfügen (Mac: ⌘V) und Enter. Beim Einfügen erscheint nichts, das ist richtig so."
step "Er steht danach nur noch hier in .env, nirgends sonst."
ask_secret MB_DHL_API_KEY "API-Schlüssel (unsichtbar; nur Enter = später):"
if [[ -z "$MB_DHL_API_KEY" ]]; then
  warn "Kein Schlüssel angekommen: DHL bleibt aus."
  write_env MB_DHL_MODE "off"
  SKIPPED+=("DHL-Labels: ./scripts/einrichten.sh dhl, sobald der API-Schlüssel da ist")
  pause
  return
fi
write_env MB_DHL_API_KEY "$MB_DHL_API_KEY"
printf '\n'
if confirm "Liegt der Systembenutzer des Geschäftskundenportals schon vor?"; then
  open_url "https://geschaeftskunden.dhl.de"
  step "Einstellungen → Benutzerverwaltung → Systembenutzer (für die API) anlegen."
  ask_real MB_DHL_USERNAME "Name des Systembenutzers:"
  ask_secret MB_DHL_PASSWORD "Passwort des Systembenutzers (unsichtbar):"
  step "Die Abrechnungsnummer hat 14 Ziffern: Kundennummer (EKP, 10), Verfahren (2), Teilnahme (2)."
  ask_real MB_DHL_EKP "Kundennummer, die ersten 10 Ziffern (EKP):"
  until [[ "$(printf '%s' "$MB_DHL_EKP" | tr -d ' ')" =~ ^[0-9]{10}$ ]]; do
    warn "Die EKP hat genau 10 Ziffern."
    ask MB_DHL_EKP "Kundennummer (EKP):"
  done
  step "Teilnahme: die letzten 2 Ziffern hinter Verfahren 01 (DHL Paket) bzw. 53 (International)."
  ask_real MB_DHL_PARTICIPATION_NATIONAL "Teilnahme DHL Paket (meist 01):" "01"
  ask_real MB_DHL_PARTICIPATION_INTERNATIONAL "Teilnahme DHL Paket International (meist 01):" "01"
  write_env MB_DHL_USERNAME "$MB_DHL_USERNAME"
  write_env MB_DHL_PASSWORD "$MB_DHL_PASSWORD"
  write_env MB_DHL_EKP "$(printf '%s' "$MB_DHL_EKP" | tr -d ' ')"
  write_env MB_DHL_PARTICIPATION_NATIONAL "$MB_DHL_PARTICIPATION_NATIONAL"
  write_env MB_DHL_PARTICIPATION_INTERNATIONAL "$MB_DHL_PARTICIPATION_INTERNATIONAL"
  step "Bucht euer DHL-Vertrag GoGreen Plus automatisch zu, meldet DHL das bei ${BOLD}make dhl-check${RESET}."
  if confirm "GoGreen Plus bei jedem Label mitbuchen?"; then
    write_env MB_DHL_GOGREEN_PLUS "true"
  else
    write_env MB_DHL_GOGREEN_PLUS "false"
  fi
  note "Erst einschalten, wenn ${BOLD}make dhl-check${RESET} beide Probesendungen angenommen hat."
  if confirm "Labels im Stellwerk jetzt echt buchen lassen?"; then
    write_env MB_DHL_MODE "production"
  else
    write_env MB_DHL_MODE "off"
    SKIPPED+=("DHL einschalten: make dhl-check, dann ./scripts/einrichten.sh dhl und einschalten")
  fi
else
  write_env MB_DHL_MODE "off"
  SKIPPED+=("DHL-Systembenutzer: ./scripts/einrichten.sh dhl, sobald er angelegt ist")
fi
step "Prüfen (bucht nichts Echtes): ${BOLD}make dhl-check SANDBOX=1${RESET} in DHLs Sandbox,"
step "${BOLD}make dhl-check${RESET} mit dem Geschäftskundenkonto. Beides nach dem Neustart."
pause
}

# substage "Title" clears the screen for the second part of the current stage.
substage() {
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# ask_ping_url KEY "Prompt": the ping URL of a check at Healthchecks.io; Enter on an empty
# value leaves the check out.
ask_ping_url() {
  local key="$1"
  ask "$key" "$2"
  until [[ -z "${!key}" || "${!key}" =~ ^https://[^[:space:]]+$ ]]; do
    warn "Die Ping-Adresse beginnt mit https://, z. B. https://hc-ping.com/…"
    ask "$key" "$2"
  done
  if [[ -n "${!key}" ]]; then
    write_env "$key" "${!key%/}"
  else
    SKIPPED+=("$key: ./scripts/einrichten.sh sicherung, sobald der Check angelegt ist")
  fi
}

# offsite_sftp runs the sftp commands on stdin on the Storage Box, with the key only.
offsite_sftp() {
  sftp -q -b - "$OFFSITE_SSH_ALIAS" >/dev/null 2>&1
}

# offsite_ssh_alias writes root's SSH host alias for the Storage Box: port 23, its own key,
# never a password prompt (cron has nobody to answer it), and the host key remembered on
# first contact. The repository then reads sftp:modellbahn-sicherung:modellbahn. Replaces
# the block an earlier run wrote.
offsite_ssh_alias() {
  install -d -m 700 "$(dirname "$OFFSITE_SSH_CONFIG")"
  touch "$OFFSITE_SSH_CONFIG"
  chmod 600 "$OFFSITE_SSH_CONFIG"
  sed -i "/^# BEGIN $OFFSITE_SSH_ALIAS\$/,/^# END $OFFSITE_SSH_ALIAS\$/d" "$OFFSITE_SSH_CONFIG"
  if [[ -s "$OFFSITE_SSH_CONFIG" && -n "$(tail -c 1 "$OFFSITE_SSH_CONFIG")" ]]; then
    printf '\n' >> "$OFFSITE_SSH_CONFIG"
  fi
  cat >> "$OFFSITE_SSH_CONFIG" <<EOF
# BEGIN $OFFSITE_SSH_ALIAS
# Hetzner Storage Box of the offsite backup (scripts/einrichten.sh sicherung, ADR 0025)
Host $OFFSITE_SSH_ALIAS
  HostName $MB_STORAGEBOX_HOST
  User $MB_STORAGEBOX_USER
  Port 23
  IdentityFile $OFFSITE_SSH_KEY
  IdentitiesOnly yes
  BatchMode yes
  StrictHostKeyChecking accept-new
  ServerAliveInterval 60
# END $OFFSITE_SSH_ALIAS
EOF
}

# show_offsite_password_once shows restic's password right after the repository was
# created: the only time it ever appears. It is not logged, and the screen is cleared after.
# shellcheck disable=SC1111
show_offsite_password_once() {
  _clear
  printf '\n%s%s  ⚠ Das Passwort der Sicherung außer Haus%s\n\n' "$BOLD" "$YELLOW" "$RESET"
  say "Die Sicherung auf der Storage Box ist verschlüsselt. Nur dieses Passwort öffnet sie."
  say "Geht dieser Server verloren, kann ohne das Passwort niemand den Shop wiederherstellen,"
  say "auch Hetzner nicht."
  printf '\n      %s%s%s\n\n' "$BOLD" "$(cat "$OFFSITE_PASSWORD_FILE")" "$RESET"
  step "Jetzt markieren, kopieren (Mac: ⌘C) und in euren Passwort-Manager legen,"
  step "z. B. als „adp-Modelle: Sicherung außer Haus“."
  step "In denselben Eintrag: Storage Box ${BOLD}$MB_STORAGEBOX_USER@$MB_STORAGEBOX_HOST${RESET}, Ordner ${BOLD}$OFFSITE_REPO_PATH${RESET}."
  warn "Dieses Skript zeigt das Passwort nie wieder an."
  printf '\n'
  until confirm "Steht das Passwort im Passwort-Manager?"; do
    [[ -t 0 ]] || break
    warn "Bitte jetzt speichern. Ohne das Passwort ist die Sicherung außer Haus wertlos."
  done
  _clear
  if [[ -t 1 ]]; then printf '\033[3J'; fi
}

# offsite_stage sets up the monitoring with Healthchecks.io and the encrypted copy of the
# nightly backup on a Hetzner Storage Box (ADR 0025). A stage of the wizard, and on its own
# with `einrichten.sh sicherung`. A second run keeps the ping URLs (Enter), the SSH key, the
# password and the repository; it never creates them anew.
# shellcheck disable=SC1111
offsite_stage() {
local repo_exists="" fresh_password=""
stage "Überwachung und Sicherung außer Haus"
say "Healthchecks.io schickt euch eine Mail, wenn der Shop nicht antwortet oder die nächtliche"
say "Sicherung fehlschlägt. Das Konto ist kostenlos."
printf '\n'
open_url "https://healthchecks.io/accounts/signup/"
step "Konto anlegen, mit der Mail-Adresse, die die Warnungen bekommen soll."
step "„Add Check“, Name ${BOLD}Shop${RESET}. Unter „Schedule“: Period ${BOLD}5 minutes${RESET}, Grace Time ${BOLD}10 minutes${RESET}."
step "Zweiter Check: Name ${BOLD}Sicherung${RESET}, Period ${BOLD}1 day${RESET}, Grace Time ${BOLD}2 hours${RESET}."
step "Jeder Check zeigt seine Ping-Adresse (https://hc-ping.com/…): kopieren und hier einfügen."
note "Weitere Empfänger: in Healthchecks.io unter „Integrations“ eine E-Mail-Adresse hinzufügen."
note "Nur Enter lässt einen Check aus."
ask_ping_url MB_HEALTHCHECK_SHOP_URL "Ping-Adresse des Checks Shop:"
ask_ping_url MB_HEALTHCHECK_BACKUP_URL "Ping-Adresse des Checks Sicherung:"
printf '*/5 * * * * root %s/scripts/ueberwachung.sh >/dev/null 2>>/var/log/modellbahn-ueberwachung.log\n' \
  "$REPO_DIR" > "$MONITOR_CRON"
chmod 644 "$MONITOR_CRON"
say "✓ $MONITOR_CRON: Alle 5 Minuten prüft der Server den Shop."
if [[ -n "$MB_HEALTHCHECK_SHOP_URL" ]]; then
  "$REPO_DIR/scripts/ueberwachung.sh" \
    || warn "Der Shop ist gerade nicht in Ordnung (oben); Healthchecks.io meldet das per Mail."
fi
pause "Weiter zur Sicherung außer Haus?"

substage "Sicherung außer Haus: Hetzner Storage Box"
say "Jede Nacht geht eine verschlüsselte Kopie der Sicherung auf eine Storage Box bei Hetzner"
say "in Deutschland. Dort bleibt sie 14 Tage, wie hier, und übersteht den Verlust dieses Servers."
printf '\n'
step "Bei Hetzner eine Storage Box bestellen; die kleinste reicht."
step "In der Hetzner-Konsole bei der Box ${BOLD}SSH-Support${RESET} und ${BOLD}Externe Erreichbarkeit${RESET} einschalten."
step "Den Vertrag zur Auftragsverarbeitung (AVV) mit Hetzner abschließen, auch in der Konsole."
step "Benutzername (u und Ziffern) und Passwort der Box bereithalten."
printf '\n'
if ! confirm "Storage Box jetzt anbinden?"; then
  SKIPPED+=("Sicherung außer Haus: ./scripts/einrichten.sh sicherung, sobald die Storage Box da ist")
  pause
  return
fi
if ! command -v restic >/dev/null 2>&1; then
  say "restic (das Sicherungsprogramm) wird installiert …"
  apt-get update -q
  apt-get install -yq restic
fi
ask_real MB_STORAGEBOX_USER "Benutzername der Storage Box (z. B. u123456):"
until [[ "$MB_STORAGEBOX_USER" =~ ^u[0-9]+(-sub[0-9]+)?$ ]]; do
  warn "Der Benutzername ist ein u mit Ziffern, z. B. u123456."
  ask MB_STORAGEBOX_USER "Benutzername der Storage Box:"
done
write_env MB_STORAGEBOX_USER "$MB_STORAGEBOX_USER"
ask_real MB_STORAGEBOX_HOST "Adresse der Storage Box:" "$MB_STORAGEBOX_USER.your-storagebox.de"
write_env MB_STORAGEBOX_HOST "$MB_STORAGEBOX_HOST"

install -d -m 700 "$(dirname "$OFFSITE_SSH_KEY")"
if [[ -f "$OFFSITE_SSH_KEY" ]]; then
  note "Der SSH-Schlüssel für die Storage Box ist schon da und bleibt."
else
  ssh-keygen -q -t ed25519 -N "" -C "modellbahn-sicherung@$(hostname)" -f "$OFFSITE_SSH_KEY"
  say "✓ Eigener SSH-Schlüssel für die Storage Box: $OFFSITE_SSH_KEY"
fi
offsite_ssh_alias
if ! offsite_sftp <<<'pwd'; then
  say "Jetzt kommt der Schlüssel auf die Storage Box. Sie fragt dafür ${BOLD}einmal${RESET} nach ihrem"
  say "Passwort. Beim Tippen oder Einfügen erscheint nichts, das ist richtig so."
  ssh -o BatchMode=no -o PubkeyAuthentication=no "$OFFSITE_SSH_ALIAS" install-ssh-key \
    < "$OFFSITE_SSH_KEY.pub" || true
fi
if ! offsite_sftp <<<'pwd'; then
  warn "Keine Verbindung zur Storage Box mit dem Schlüssel."
  note "Prüfen: SSH-Support und Externe Erreichbarkeit an? Benutzername, Adresse und Passwort richtig?"
  SKIPPED+=("Sicherung außer Haus: Verbindung zur Storage Box klären, dann ./scripts/einrichten.sh sicherung")
  pause
  return
fi
say "✓ Die Storage Box nimmt den Schlüssel an."

write_env MB_RESTIC_REPOSITORY "sftp:$OFFSITE_SSH_ALIAS:$OFFSITE_REPO_PATH"
install -d -m 700 "$(dirname "$OFFSITE_PASSWORD_FILE")"
if offsite_sftp <<<"ls $OFFSITE_REPO_PATH/config"; then repo_exists=1; fi
if [[ -s "$OFFSITE_PASSWORD_FILE" ]]; then
  note "Das Passwort der Sicherung ist schon gesetzt und bleibt."
elif [[ -n "$repo_exists" ]]; then
  say "Auf der Storage Box liegt schon eine Sicherung, etwa vom alten Server. Sie öffnet sich"
  say "nur mit ihrem Passwort aus eurem Passwort-Manager."
  ask_secret OFFSITE_PASSWORD_INPUT "Passwort der Sicherung außer Haus (unsichtbar):"
  (umask 077 && printf '%s\n' "$OFFSITE_PASSWORD_INPUT" > "$OFFSITE_PASSWORD_FILE")
  fresh_password=1
else
  (umask 077 && openssl rand -hex 24 > "$OFFSITE_PASSWORD_FILE")
fi
chmod 600 "$OFFSITE_PASSWORD_FILE"

if [[ -n "$repo_exists" ]]; then
  if offsite_restic cat config >/dev/null 2>&1; then
    say "✓ Die Sicherung auf der Storage Box öffnet sich mit dem Passwort."
  else
    warn "Das Passwort öffnet die Sicherung auf der Storage Box nicht."
    if [[ -n "$fresh_password" ]]; then
      rm -f "$OFFSITE_PASSWORD_FILE"
    else
      note "Stimmt das Passwort im Passwort-Manager, die Datei $OFFSITE_PASSWORD_FILE löschen"
      note "und das Skript erneut starten; es fragt dann danach."
    fi
    SKIPPED+=("Sicherung außer Haus: Passwort klären, dann ./scripts/einrichten.sh sicherung")
    pause
    return
  fi
elif offsite_restic init >/dev/null; then
  say "✓ Neue, verschlüsselte Sicherung auf der Storage Box angelegt."
  pause "Enter zeigt das Passwort der Sicherung. Den Passwort-Manager schon öffnen."
  show_offsite_password_once
else
  warn "Die Sicherung auf der Storage Box ließ sich nicht anlegen (Meldung oben)."
  SKIPPED+=("Sicherung außer Haus: ./scripts/einrichten.sh sicherung erneut starten")
  pause
  return
fi

printf '\n'
say "Ab heute Nacht geht jede Sicherung auch auf die Storage Box und bleibt dort 14 Tage."
if confirm "Jetzt einmal sichern, mit Kopie außer Haus (die Bilder sind dabei kurz nicht erreichbar)?"; then
  if "$REPO_DIR/scripts/sicherung.sh"; then
    if confirm "Und zur Probe wiederherstellen? Der Shop läuft dabei weiter."; then
      "$REPO_DIR/scripts/sicherung_pruefen.sh" \
        || SKIPPED+=("Probe-Wiederherstellung: make sicherung-pruefen, Meldung prüfen")
    fi
  else
    warn "Die Sicherung ist fehlgeschlagen (Meldung oben)."
    SKIPPED+=("Sicherung: ./scripts/sicherung.sh von Hand starten und die Meldung prüfen")
  fi
fi
pause
}

run_wizard() {

TOTAL_STAGES=14

if [[ $EUID -ne 0 ]]; then
  printf 'Bitte als root starten: sudo %s\n' "$0" >&2
  exit 1
fi
cd "$REPO_DIR"
if [[ ! -f "$ENV_FILE" ]]; then
  (umask 077 && cp .env.example "$ENV_FILE")
fi
chmod 600 "$ENV_FILE"

if [[ "${1:-}" == "dhl" ]]; then
  TOTAL_STAGES=2
  banner "DHL-Versandlabels einrichten"
  dhl_stage
  stage "Shop neu starten"
  say "Damit der Shop die DHL-Einstellungen liest, wird er neu gebaut und gestartet."
  say "Das dauert ein paar Minuten; der Shop läuft währenddessen weiter."
  if confirm "Jetzt neu bauen und starten?"; then
    docker compose up --detach --build --wait
    say "✓ Neu gestartet."
  else
    SKIPPED+=("Neu starten: docker compose up --detach --build --wait")
  fi
  finish
  say "Prüfen: make dhl-check SANDBOX=1 (Sandbox) · make dhl-check (Geschäftskundenkonto)"
  return
fi

if [[ "${1:-}" == "sicherung" ]]; then
  TOTAL_STAGES=1
  banner "Überwachung und Sicherung außer Haus einrichten"
  offsite_stage
  finish
  say "Prüfen: make sicherung-pruefen (Probe-Wiederherstellung) · ./scripts/ueberwachung.sh"
  return
fi

banner "Modellbahn-Shop auf dem Strato-Server einrichten"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Grundsystem: Updates und Firewall"
say "Der Server bekommt die neuesten Pakete, die Werkzeuge für den Shop und eine Firewall,"
say "die nur SSH (22), HTTP (80) und HTTPS (443) durchlässt."
warn "SSH bleibt offen, die Verbindung bricht nicht ab."
if confirm "Jetzt aktualisieren und die Firewall einschalten?"; then
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -q
  # Changed configuration files (e.g. of SSH) keep their current version.
  apt-get upgrade -yq -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold
  apt-get install -yq ufw unattended-upgrades git make curl dnsutils openssl ca-certificates
  ufw allow OpenSSH
  ufw allow 80/tcp
  ufw allow 443/tcp
  ufw allow 443/udp
  ufw --force enable
  dpkg-reconfigure -f noninteractive unattended-upgrades
  say "✓ Aktuell; Sicherheitsupdates spielt der Server ab jetzt selbst ein."
else
  SKIPPED+=("Grundsystem: Updates und Firewall")
fi
note "Hat dein Strato-Paket im Server-Login eine eigene Firewall, gib dort ebenfalls 80 und 443 frei."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Docker"
if command -v docker >/dev/null 2>&1 && docker compose version >/dev/null 2>&1; then
  say "✓ Docker ist schon da: $(docker --version)"
else
  say "Docker kommt aus der offiziellen Paketquelle von Docker."
  install -m 0755 -d /etc/apt/keyrings
  curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc
  chmod a+r /etc/apt/keyrings/docker.asc
  # shellcheck disable=SC1091
  codename="$(. /etc/os-release && echo "$VERSION_CODENAME")"
  printf 'deb [arch=%s signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/ubuntu %s stable\n' \
    "$(dpkg --print-architecture)" "$codename" > /etc/apt/sources.list.d/docker.list
  apt-get update -q
  apt-get install -yq docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  say "✓ $(docker --version)"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Domain: die Shop-Adresse zeigt auf diesen Server"
ipv4="$(public_ipv4)"
ipv6="$(public_ipv6)"
say "Dieser Server hat die Adressen:"
step "IPv4: ${BOLD}${ipv4:-unbekannt}${RESET}"
[[ -n "$ipv6" ]] && step "IPv6: ${BOLD}${ipv6}${RESET}"
printf '\n'
ask_real SITE_ADDRESS "Unter welcher Adresse soll der Shop laufen?" "$DEFAULT_SITE"
write_env SITE_ADDRESS "$SITE_ADDRESS"
write_env MB_PUBLIC_BASE_URL "https://$SITE_ADDRESS"
printf '\n'
say "Jetzt im Strato-Kundenlogin den DNS-Eintrag anlegen:"
open_url "https://www.strato.de/apps/CustomerService"
step "Domains → Domainverwaltung. Bei adp-modelle.de eine Subdomain „${SITE_ADDRESS%%.*}“ anlegen."
step "Bei der neuen Subdomain (Zahnrad) → DNS → A-Record verwalten: diese IPv4-Adresse eintragen."
[[ -n "$ipv6" ]] && step "Dort auch den AAAA-Record auf die IPv6-Adresse setzen."
warn "www.adp-modelle.de und adp-modelle.de nicht anfassen: dort läuft weiter Shopify."
note "Die Menüs heißen je nach Strato-Paket leicht anders; gesucht ist der A-Record der Subdomain."
pause "Eingetragen? Enter prüft, ob die Adresse schon auf diesen Server zeigt."
resolved=""
for _ in $(seq 1 60); do
  resolved="$(dig +short A "$SITE_ADDRESS" @1.1.1.1 2>/dev/null | tail -n1 || true)"
  [[ -n "$ipv4" && "$resolved" == "$ipv4" ]] && break
  printf '  %swarte auf DNS: %s → %s%s\r' "$DIM" "$SITE_ADDRESS" "${resolved:-noch nichts}" "$RESET"
  sleep 10
done
printf '\n'
if [[ "$resolved" == "$ipv4" ]]; then
  say "✓ $SITE_ADDRESS zeigt auf $ipv4."
else
  warn "$SITE_ADDRESS zeigt noch nicht hierher (${resolved:-kein Eintrag}). Ohne das gibt es kein HTTPS-Zertifikat."
  confirm "Trotzdem weiter?" || exit 1
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Mail: ein Strato-Postfach verschickt die Mails des Shops"
say "Bestätigungen, Bestellungen und Passwort-Links gehen über ein Postfach bei Strato,"
say "z. B. shop@adp-modelle.de. Gibt es noch keins, lege es jetzt an:"
open_url "https://www.strato.de/apps/CustomerService"
step "E-Mail → Verwalten → Postfach anlegen (oder ein vorhandenes nehmen) und das Passwort notieren."
printf '\n'
ask_real MB_SMTP_USERNAME "E-Mail-Adresse des Postfachs:"
ask_secret MB_SMTP_PASSWORD "Passwort des Postfachs (unsichtbar):"
shop_name="$(_existing NEXT_PUBLIC_SHOP_NAME || echo "adp-Modelle")"
write_env MB_SMTP_HOST "smtp.strato.de"
write_env MB_SMTP_PORT "587"
write_env MB_SMTP_STARTTLS "true"
write_env MB_SMTP_USERNAME "$MB_SMTP_USERNAME"
write_env MB_SMTP_PASSWORD "$MB_SMTP_PASSWORD"
write_env MB_SMTP_FROM "$shop_name <$MB_SMTP_USERNAME>"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Impressum"
say "Diese Angaben stehen unter /impressum und unter jeder Mail. Sie bleiben nur in .env"
say "auf diesem Server. Ohne sie startet der Shop im echten Betrieb nicht."
printf '\n'
ask_real MB_IMPRINT_COMPANY "Firma (wie im Impressum):"
ask_real MB_IMPRINT_OWNER "Inhaber (Vor- und Nachname):"
ask_real MB_IMPRINT_STREET "Straße und Hausnummer:"
ask_real MB_IMPRINT_POSTAL_CODE "Postleitzahl:"
ask_real MB_IMPRINT_CITY "Ort:"
ask_real MB_IMPRINT_EMAIL "E-Mail für Kunden:"
ask_real MB_IMPRINT_PHONE "Telefon (leer lassen, wenn keins):"
ask_real MB_IMPRINT_VAT_ID "USt-IdNr. (DE und 9 Ziffern; leer lassen, wenn keine):"
for key in MB_IMPRINT_COMPANY MB_IMPRINT_OWNER MB_IMPRINT_STREET MB_IMPRINT_POSTAL_CODE \
  MB_IMPRINT_CITY MB_IMPRINT_EMAIL; do
  write_env "$key" "${!key}"
done
for key in MB_IMPRINT_PHONE MB_IMPRINT_VAT_ID; do
  if [[ -n "${!key}" ]]; then write_env "$key" "${!key}"; else sed -i "/^${key}=/d" "$ENV_FILE"; fi
done
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Echter Betrieb und eigene Geheimnisse"
say "Jetzt würfelt der Server seine eigenen Passwörter und Schlüssel. Du musst sie dir nicht"
say "merken; sie stehen in .env (nur für root lesbar) und landen in der nächtlichen Sicherung."
printf '\n'
keep_or_generate POSTGRES_PASSWORD "openssl rand -hex 24"
keep_or_generate GARAGE_RPC_SECRET "openssl rand -hex 32"
keep_or_generate GARAGE_ADMIN_TOKEN "openssl rand -base64 32"
keep_or_generate MB_S3_ACCESS_KEY_ID 'printf "GK%s" "$(openssl rand -hex 12)"'
keep_or_generate MB_S3_SECRET_ACCESS_KEY "openssl rand -hex 32"
keep_or_generate MB_EBAY_TOKEN_KEY "openssl rand -base64 32 | tr '+/' '-_'"
keep_or_generate MB_EBAY_VERIFICATION_TOKEN "openssl rand -base64 48 | tr '+/' '-_' | tr -d '='"
write_env MB_ENVIRONMENT "production"
write_env CADDY_TLS "$MB_IMPRINT_EMAIL"
write_env CADDY_HSTS "max-age=31536000"
write_env COMPOSE_FILE "docker-compose.yml:docker-compose.prod.yml"
note "Das HTTPS-Zertifikat holt Caddy bei Let's Encrypt; Hinweise gehen an $MB_IMPRINT_EMAIL."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "eBay (kann später nachgeholt werden)"
say "Damit eBay die Produktions-Schlüssel freigibt, muss dieser Server eBays Löschmeldungen"
say "annehmen. Trag im eBay-Entwicklerkonto unter „Alerts & Notifications“ ein:"
step "Endpunkt: ${BOLD}https://$SITE_ADDRESS/api/v1/webhooks/ebay/account-deletion${RESET}"
step "Verification token: ${BOLD}$(_existing MB_EBAY_VERIFICATION_TOKEN)${RESET}"
note "Das klappt erst, wenn der Shop läuft (Schritt 10); eBay prüft die Adresse beim Speichern."
printf '\n'
if confirm "Johanns eBay-Schlüssel jetzt eintragen?"; then
  open_url "https://developer.ebay.com/my/keys"
  step "Application Keysets → Production: App ID (Client ID) und Cert ID (Client Secret) kopieren."
  ask MB_EBAY_CLIENT_ID "App ID (Client ID):"
  ask_secret MB_EBAY_CLIENT_SECRET "Cert ID (Client Secret, unsichtbar):"
  step "User Tokens → „Get a Token from eBay via Your Application“ → RuName anlegen;"
  step "als „Auth accepted URL“: ${BOLD}https://$SITE_ADDRESS/api/v1/admin/marketplace/ebay/callback${RESET}"
  ask MB_EBAY_RU_NAME "RuName (eBay Redirect URL name):"
  write_env MB_EBAY_CLIENT_ID "$MB_EBAY_CLIENT_ID"
  write_env MB_EBAY_CLIENT_SECRET "$MB_EBAY_CLIENT_SECRET"
  write_env MB_EBAY_RU_NAME "$MB_EBAY_RU_NAME"
  write_env MB_EBAY_MODE "production"
else
  write_env MB_EBAY_MODE "off"
  SKIPPED+=("eBay-Schlüssel: Skript erneut starten, sobald sie da sind")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Zahlung mit SumUp"
say "Kunden bezahlen auf der Seite von SumUp: mit Karte, je nach Gerät auch mit Apple Pay oder"
say "Google Pay. Der Shop braucht dafür einen API-Schlüssel des SumUp-Kontos und den Händlercode."
note "Ohne SumUp nimmt der Shop keine Bestellungen an; die Testzahlung gibt es nur auf dem Laptop."
printf '\n'
if confirm "SumUp jetzt anbinden?"; then
  open_url "https://developer.sumup.com/tools/authorization"
  step "Im SumUp-Konto unter den Entwickler-Einstellungen einen API-Schlüssel anlegen."
  step "Er beginnt mit ${BOLD}sup_sk_${RESET} und steht danach nur noch hier in .env, nirgends sonst."
  ask_secret MB_SUMUP_API_KEY "API-Schlüssel (unsichtbar):"
  until [[ "$MB_SUMUP_API_KEY" == sup_sk_* ]]; do
    warn "Ein geheimer SumUp-Schlüssel beginnt mit sup_sk_ (nicht sup_pk_)."
    ask_secret MB_SUMUP_API_KEY "API-Schlüssel (unsichtbar):"
  done
  step "Den Händlercode zeigt das SumUp-Konto im Profil, z. B. ${BOLD}MC123456789${RESET}."
  ask_real MB_SUMUP_MERCHANT_CODE "Händlercode:"
  write_env MB_SUMUP_API_KEY "$MB_SUMUP_API_KEY"
  write_env MB_SUMUP_MERCHANT_CODE "$MB_SUMUP_MERCHANT_CODE"
  write_env MB_PAYMENT_PROVIDER "sumup"
  note "Wohin SumUp Bescheid gibt, nennt der Shop bei jeder Zahlung selbst:"
  note "https://$SITE_ADDRESS/api/v1/webhooks/sumup. Im SumUp-Konto ist dafür nichts einzutragen."
else
  write_env MB_PAYMENT_PROVIDER "off"
  SKIPPED+=("SumUp: bis dahin nimmt der Shop keine Bestellungen an; Skript erneut starten")
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Vorkasse per Überweisung (kann später nachgeholt werden)"
say "Kunden können statt über SumUp auch per Überweisung bezahlen. Der Shop zeigt ihnen dafür"
say "die Bankverbindung, die Bestellnummer als Verwendungszweck und einen GiroCode für die"
say "Banking-App. Ihr bucht den Zahlungseingang im Stellwerk mit einem Klick."
note "Ohne Bankverbindung gibt es nur die Zahlung über SumUp."
printf '\n'
if confirm "Vorkasse anbieten (Bankverbindung eintragen)?"; then
  ask_real MB_BANK_ACCOUNT_HOLDER "Kontoinhaber, wie er auf der Überweisung stehen soll:"
  ask_real MB_BANK_IBAN "IBAN:"
  until iban_ok "$MB_BANK_IBAN"; do
    warn "Das ist keine gültige IBAN (Prüfziffer) oder nur das Beispielkonto."
    ask MB_BANK_IBAN "IBAN:"
  done
  ask_real MB_BANK_BIC "BIC (leer lassen, wenn unbekannt):"
  ask_real MB_BANK_NAME "Name der Bank (leer lassen, wenn egal):"
  write_env MB_BANK_ACCOUNT_HOLDER "$MB_BANK_ACCOUNT_HOLDER"
  write_env MB_BANK_IBAN "$(printf '%s' "$MB_BANK_IBAN" | tr -d ' ' | tr '[:lower:]' '[:upper:]')"
  write_env MB_BANK_BIC "$(printf '%s' "$MB_BANK_BIC" | tr -d ' ' | tr '[:lower:]' '[:upper:]')"
  write_env MB_BANK_NAME "$MB_BANK_NAME"
else
  for key in MB_BANK_ACCOUNT_HOLDER MB_BANK_IBAN MB_BANK_BIC MB_BANK_NAME; do
    sed -i "/^${key}=/d" "$ENV_FILE"
  done
  SKIPPED+=("Vorkasse: Skript erneut starten und die Bankverbindung eintragen")
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
dhl_stage

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Shop bauen und starten"
say "Der erste Bau dauert 10 bis 20 Minuten; danach startet der Shop mit HTTPS."
if confirm "Jetzt bauen und starten?"; then
  docker compose up --detach --build --wait
  say "Warte auf https://$SITE_ADDRESS …"
  ready=""
  for _ in $(seq 1 30); do
    if curl -fsS --max-time 10 "https://$SITE_ADDRESS/readyz" >/dev/null 2>&1; then ready=1; break; fi
    sleep 10
  done
  if [[ -n "$ready" ]]; then
    say "✓ Der Shop antwortet unter https://$SITE_ADDRESS"
  else
    warn "Noch keine Antwort über HTTPS. Logs: docker compose logs caddy api"
    SKIPPED+=("Shop antwortet noch nicht über HTTPS: docker compose logs caddy api")
  fi
else
  SKIPPED+=("Shop starten: docker compose up --detach --build --wait")
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Konten für das Stellwerk"
say "Das erste Konto bekommt die Rolle Inhaber. Das Passwort fragt das Programm gleich ab"
say "(mindestens 12 Zeichen)."
printf '\n'
ask STAFF_EMAIL "Deine E-Mail-Adresse für die Anmeldung:"
ask STAFF_NAME "Dein Name, wie er im Stellwerk steht:"
make staff EMAIL="$STAFF_EMAIL" NAME="$STAFF_NAME" ROLE=owner || SKIPPED+=("Inhaberkonto: make staff EMAIL=… NAME=\"…\" ROLE=owner")
if confirm "Auch ein Konto für Johann anlegen?"; then
  ask JOHANN_EMAIL "Johanns E-Mail-Adresse:"
  ask JOHANN_NAME "Johanns Name:"
  ask JOHANN_ROLE "Rolle (owner, staff oder packer):"
  make staff EMAIL="$JOHANN_EMAIL" NAME="$JOHANN_NAME" ROLE="${JOHANN_ROLE:-owner}" \
    || SKIPPED+=("Konto für Johann: make staff EMAIL=… NAME=\"…\" ROLE=…")
fi
step "Anmelden: ${BOLD}https://$SITE_ADDRESS/admin${RESET}"
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Nächtliche Sicherung"
say "Jede Nacht um 3:30 sichert der Server Datenbank und Bilder nach /var/backups/modellbahn"
say "und hält 14 Tage vor."
printf '30 3 * * * root %s/scripts/sicherung.sh >> /var/log/modellbahn-sicherung.log 2>&1\n' \
  "$REPO_DIR" > /etc/cron.d/modellbahn-sicherung
chmod 644 /etc/cron.d/modellbahn-sicherung
say "✓ /etc/cron.d/modellbahn-sicherung"
if confirm "Jetzt einmal zur Probe sichern (die Bilder sind dabei kurz nicht erreichbar)?"; then
  "$REPO_DIR/scripts/sicherung.sh" || {
    warn "Die Sicherung ist fehlgeschlagen (Meldung oben)."
    SKIPPED+=("Sicherung: ./scripts/sicherung.sh von Hand starten und die Meldung prüfen")
  }
fi
warn "Sicherungen auf demselben Server überstehen dessen Verlust nicht. Dafür kommt im nächsten"
warn "Schritt die Sicherung außer Haus."
pause

# ── 14 ────────────────────────────────────────────────────────────────────
offsite_stage

finish
say "Stellwerk: https://$SITE_ADDRESS/admin"
say "Aktualisieren: cd $REPO_DIR && git pull && docker compose up --detach --build --wait"
note "Repository: https://github.com/$GITHUB_REPO"
}

run_wizard "$@"; exit
